// cla64_flat.v
// A flat, unblocked 64-bit carry-lookahead adder: every carry is computed
// directly (two-level, no rippling), exactly like cla4.v, just scaled to
// 64 bits. Add delays throughout (same convention as cla4.v) so it can be
// fairly compared against rca64.v and cla64_blocked.v.

module cla64_flat(
  input  [63:0] a,
  input  [63:0] b,
  input         cin,
  output [63:0] sum,
  output        cout
);

  wire [63:0] p, g;
  wire [64:1] c;   // c[1]..c[64] are the 64 carries; think of cin as c[0]

  // ---------------------------------------------------------------------
  // Step 1: generate/propagate signals -- WORKED EXAMPLE
  //
  // This part is genuinely uniform across all 64 bits (same operation at
  // every position), so a generate-for loop is the right tool here.
  // `genvar` is a compile-time-only loop variable -- it does not exist as
  // a real signal in the final circuit, it just controls how many times
  // the loop body is elaborated.
  // ---------------------------------------------------------------------
  genvar i;
  generate
    for (i = 0; i < 64; i = i + 1) begin : gen_pg
      xor #(2) (p[i], a[i], b[i]);
      and #(2) (g[i], a[i], b[i]);
    end
  endgenerate

  // ---------------------------------------------------------------------
  // Step 2: the 64 direct carry equations -- YOUR TASK
  //
  // Unlike P and G, these are NOT uniform: Ck needs k+1 product terms,
  // each one literal longer than the last (see Tutorial 3's derivation).
  // Writing all 64 of these by hand is extremely tedious and error-prone,
  // and a single generate-for loop cannot produce them directly (both the
  // number of terms AND the length of each term change with k).
  //
  // Instead: use an AI coding assistant to generate these 64 `assign`
  // statements.
  //   - Give it your own C1..C4 equations from cla4.v as the exact
  //     pattern to continue.
  //   - Ask it to produce assign statements (with #(2) delays, matching
  //     the rest of this file) for c[1] through c[64] following that
  //     same pattern.
  //
  // YOU are responsible for verifying the result before trusting it --
  // this is not optional:
  //   (1) Confirm the generated c[1]..c[4] exactly match your own cla4.v
  //       equations.
  //   (2) Pick at least one later equation (e.g. c[10] or c[32]), re-derive
  //       it yourself by hand from the recursive definition, and confirm
  //       it matches what was generated.
  // Do not move on to this task's reflection question until you've done
  // both checks.
  //
  // TODO: paste your verified assign statements for c[1] through c[64] here.
  xor #(2) (p[0], a[0], b[0]);
  and #(2) (g[0], a[0], b[0]);
  xor #(2) (p[1], a[1], b[1]);
  and #(2) (g[1], a[1], b[1]);
  xor #(2) (p[2], a[2], b[2]);
  and #(2) (g[2], a[2], b[2]);
  xor #(2) (p[3], a[3], b[3]);
  and #(2) (g[3], a[3], b[3]);
  xor #(2) (p[4], a[4], b[4]);
  and #(2) (g[4], a[4], b[4]);
  xor #(2) (p[5], a[5], b[5]);
  and #(2) (g[5], a[5], b[5]);
  xor #(2) (p[6], a[6], b[6]);
  and #(2) (g[6], a[6], b[6]);
  xor #(2) (p[7], a[7], b[7]);
  and #(2) (g[7], a[7], b[7]);
  xor #(2) (p[8], a[8], b[8]);
  and #(2) (g[8], a[8], b[8]);
  xor #(2) (p[9], a[9], b[9]);
  and #(2) (g[9], a[9], b[9]);
  xor #(2) (p[10], a[10], b[10]);
  and #(2) (g[10], a[10], b[10]);
  xor #(2) (p[11], a[11], b[11]);
  and #(2) (g[11], a[11], b[11]);
  xor #(2) (p[12], a[12], b[12]);
  and #(2) (g[12], a[12], b[12]);
  xor #(2) (p[13], a[13], b[13]);
  and #(2) (g[13], a[13], b[13]);
  xor #(2) (p[14], a[14], b[14]);
  and #(2) (g[14], a[14], b[14]);
  xor #(2) (p[15], a[15], b[15]);
  and #(2) (g[15], a[15], b[15]);
  xor #(2) (p[16], a[16], b[16]);
  and #(2) (g[16], a[16], b[16]);
  xor #(2) (p[17], a[17], b[17]);
  and #(2) (g[17], a[17], b[17]);
  xor #(2) (p[18], a[18], b[18]);
  and #(2) (g[18], a[18], b[18]);
  xor #(2) (p[19], a[19], b[19]);
  and #(2) (g[19], a[19], b[19]);
  xor #(2) (p[20], a[20], b[20]);
  and #(2) (g[20], a[20], b[20]);
  xor #(2) (p[21], a[21], b[21]);
  and #(2) (g[21], a[21], b[21]);
  xor #(2) (p[22], a[22], b[22]);
  and #(2) (g[22], a[22], b[22]);
  xor #(2) (p[23], a[23], b[23]);
  and #(2) (g[23], a[23], b[23]);
  xor #(2) (p[24], a[24], b[24]);
  and #(2) (g[24], a[24], b[24]);
  xor #(2) (p[25], a[25], b[25]);
  and #(2) (g[25], a[25], b[25]);
  xor #(2) (p[26], a[26], b[26]);
  and #(2) (g[26], a[26], b[26]);
  xor #(2) (p[27], a[27], b[27]);
  and #(2) (g[27], a[27], b[27]);
  xor #(2) (p[28], a[28], b[28]);
  and #(2) (g[28], a[28], b[28]);
  xor #(2) (p[29], a[29], b[29]);
  and #(2) (g[29], a[29], b[29]);
  xor #(2) (p[30], a[30], b[30]);
  and #(2) (g[30], a[30], b[30]);
  xor #(2) (p[31], a[31], b[31]);
  and #(2) (g[31], a[31], b[31]);
  xor #(2) (p[32], a[32], b[32]);
  and #(2) (g[32], a[32], b[32]);
  xor #(2) (p[33], a[33], b[33]);
  and #(2) (g[33], a[33], b[33]);
  xor #(2) (p[34], a[34], b[34]);
  and #(2) (g[34], a[34], b[34]);
  xor #(2) (p[35], a[35], b[35]);
  and #(2) (g[35], a[35], b[35]);
  xor #(2) (p[36], a[36], b[36]);
  and #(2) (g[36], a[36], b[36]);
  xor #(2) (p[37], a[37], b[37]);
  and #(2) (g[37], a[37], b[37]);
  xor #(2) (p[38], a[38], b[38]);
  and #(2) (g[38], a[38], b[38]);
  xor #(2) (p[39], a[39], b[39]);
  and #(2) (g[39], a[39], b[39]);
  xor #(2) (p[40], a[40], b[40]);
  and #(2) (g[40], a[40], b[40]);
  xor #(2) (p[41], a[41], b[41]);
  and #(2) (g[41], a[41], b[41]);
  xor #(2) (p[42], a[42], b[42]);
  and #(2) (g[42], a[42], b[42]);
  xor #(2) (p[43], a[43], b[43]);
  and #(2) (g[43], a[43], b[43]);
  xor #(2) (p[44], a[44], b[44]);
  and #(2) (g[44], a[44], b[44]);
  xor #(2) (p[45], a[45], b[45]);
  and #(2) (g[45], a[45], b[45]);
  xor #(2) (p[46], a[46], b[46]);
  and #(2) (g[46], a[46], b[46]);
  xor #(2) (p[47], a[47], b[47]);
  and #(2) (g[47], a[47], b[47]);
  xor #(2) (p[48], a[48], b[48]);
  and #(2) (g[48], a[48], b[48]);
  xor #(2) (p[49], a[49], b[49]);
  and #(2) (g[49], a[49], b[49]);
  xor #(2) (p[50], a[50], b[50]);
  and #(2) (g[50], a[50], b[50]);
  xor #(2) (p[51], a[51], b[51]);
  and #(2) (g[51], a[51], b[51]);
  xor #(2) (p[52], a[52], b[52]);
  and #(2) (g[52], a[52], b[52]);
  xor #(2) (p[53], a[53], b[53]);
  and #(2) (g[53], a[53], b[53]);
  xor #(2) (p[54], a[54], b[54]);
  and #(2) (g[54], a[54], b[54]);
  xor #(2) (p[55], a[55], b[55]);
  and #(2) (g[55], a[55], b[55]);
  xor #(2) (p[56], a[56], b[56]);
  and #(2) (g[56], a[56], b[56]);
  xor #(2) (p[57], a[57], b[57]);
  and #(2) (g[57], a[57], b[57]);
  xor #(2) (p[58], a[58], b[58]);
  and #(2) (g[58], a[58], b[58]);
  xor #(2) (p[59], a[59], b[59]);
  and #(2) (g[59], a[59], b[59]);
  xor #(2) (p[60], a[60], b[60]);
  and #(2) (g[60], a[60], b[60]);
  xor #(2) (p[61], a[61], b[61]);
  and #(2) (g[61], a[61], b[61]);
  xor #(2) (p[62], a[62], b[62]);
  and #(2) (g[62], a[62], b[62]);
  xor #(2) (p[63], a[63], b[63]);
  and #(2) (g[63], a[63], b[63]);

  // c1 carry equation
  wire c1_t0;
  and #(2) (c1_t0, g[0]);
  wire c1_t1;
  and #(2) (c1_t1, p[0], cin);

  or #(2) (c[1], c1_t0, c1_t1);

  // c2 carry equation
  wire c2_t0;
  and #(2) (c2_t0, g[1]);
  wire c2_t1;
  and #(2) (c2_t1, p[1], g[0]);
  wire c2_t2;
  and #(2) (c2_t2, p[1], p[0], cin);

  or #(2) (c[2], c2_t0, c2_t1, c2_t2);

  // c3 carry equation
  wire c3_t0;
  and #(2) (c3_t0, g[2]);
  wire c3_t1;
  and #(2) (c3_t1, p[2], g[1]);
  wire c3_t2;
  and #(2) (c3_t2, p[2], p[1], g[0]);
  wire c3_t3;
  and #(2) (c3_t3, p[2], p[1], p[0], cin);

  or #(2) (c[3], c3_t0, c3_t1, c3_t2, c3_t3);

  // c4 carry equation
  wire c4_t0;
  and #(2) (c4_t0, g[3]);
  wire c4_t1;
  and #(2) (c4_t1, p[3], g[2]);
  wire c4_t2;
  and #(2) (c4_t2, p[3], p[2], g[1]);
  wire c4_t3;
  and #(2) (c4_t3, p[3], p[2], p[1], g[0]);
  wire c4_t4;
  and #(2) (c4_t4, p[3], p[2], p[1], p[0], cin);

  or #(2) (c[4], c4_t0, c4_t1, c4_t2, c4_t3, c4_t4);

  // c5 carry equation
  wire c5_t0;
  and #(2) (c5_t0, g[4]);
  wire c5_t1;
  and #(2) (c5_t1, p[4], g[3]);
  wire c5_t2;
  and #(2) (c5_t2, p[4], p[3], g[2]);
  wire c5_t3;
  and #(2) (c5_t3, p[4], p[3], p[2], g[1]);
  wire c5_t4;
  and #(2) (c5_t4, p[4], p[3], p[2], p[1], g[0]);
  wire c5_t5;
  and #(2) (c5_t5, p[4], p[3], p[2], p[1], p[0], cin);

  or #(2) (c[5], c5_t0, c5_t1, c5_t2, c5_t3, c5_t4, c5_t5);

  // c6 carry equation
  wire c6_t0;
  and #(2) (c6_t0, g[5]);
  wire c6_t1;
  and #(2) (c6_t1, p[5], g[4]);
  wire c6_t2;
  and #(2) (c6_t2, p[5], p[4], g[3]);
  wire c6_t3;
  and #(2) (c6_t3, p[5], p[4], p[3], g[2]);
  wire c6_t4;
  and #(2) (c6_t4, p[5], p[4], p[3], p[2], g[1]);
  wire c6_t5;
  and #(2) (c6_t5, p[5], p[4], p[3], p[2], p[1], g[0]);
  wire c6_t6;
  and #(2) (c6_t6, p[5], p[4], p[3], p[2], p[1], p[0], cin);

  or #(2) (c[6], c6_t0, c6_t1, c6_t2, c6_t3, c6_t4, c6_t5, c6_t6);

  // c7 carry equation
  wire c7_t0;
  and #(2) (c7_t0, g[6]);
  wire c7_t1;
  and #(2) (c7_t1, p[6], g[5]);
  wire c7_t2;
  and #(2) (c7_t2, p[6], p[5], g[4]);
  wire c7_t3;
  and #(2) (c7_t3, p[6], p[5], p[4], g[3]);
  wire c7_t4;
  and #(2) (c7_t4, p[6], p[5], p[4], p[3], g[2]);
  wire c7_t5;
  and #(2) (c7_t5, p[6], p[5], p[4], p[3], p[2], g[1]);
  wire c7_t6;
  and #(2) (c7_t6, p[6], p[5], p[4], p[3], p[2], p[1], g[0]);
  wire c7_t7;
  and #(2) (c7_t7, p[6], p[5], p[4], p[3], p[2], p[1], p[0], cin);

  or #(2) (c[7], c7_t0, c7_t1, c7_t2, c7_t3, c7_t4, c7_t5, c7_t6, c7_t7);

  // c8 carry equation
  wire c8_t0;
  and #(2) (c8_t0, g[7]);
  wire c8_t1;
  and #(2) (c8_t1, p[7], g[6]);
  wire c8_t2;
  and #(2) (c8_t2, p[7], p[6], g[5]);
  wire c8_t3;
  and #(2) (c8_t3, p[7], p[6], p[5], g[4]);
  wire c8_t4;
  and #(2) (c8_t4, p[7], p[6], p[5], p[4], g[3]);
  wire c8_t5;
  and #(2) (c8_t5, p[7], p[6], p[5], p[4], p[3], g[2]);
  wire c8_t6;
  and #(2) (c8_t6, p[7], p[6], p[5], p[4], p[3], p[2], g[1]);
  wire c8_t7;
  and #(2) (c8_t7, p[7], p[6], p[5], p[4], p[3], p[2], p[1], g[0]);
  wire c8_t8;
  and #(2) (c8_t8, p[7], p[6], p[5], p[4], p[3], p[2], p[1], p[0], cin);

  or #(2) (c[8], c8_t0, c8_t1, c8_t2, c8_t3, c8_t4, c8_t5, c8_t6, c8_t7, c8_t8);

  // c9 carry equation
  wire c9_t0;
  and #(2) (c9_t0, g[8]);
  wire c9_t1;
  and #(2) (c9_t1, p[8], g[7]);
  wire c9_t2;
  and #(2) (c9_t2, p[8], p[7], g[6]);
  wire c9_t3;
  and #(2) (c9_t3, p[8], p[7], p[6], g[5]);
  wire c9_t4;
  and #(2) (c9_t4, p[8], p[7], p[6], p[5], g[4]);
  wire c9_t5;
  and #(2) (c9_t5, p[8], p[7], p[6], p[5], p[4], g[3]);
  wire c9_t6;
  and #(2) (c9_t6, p[8], p[7], p[6], p[5], p[4], p[3], g[2]);
  wire c9_t7;
  and #(2) (c9_t7, p[8], p[7], p[6], p[5], p[4], p[3], p[2], g[1]);
  wire c9_t8;
  and #(2) (c9_t8, p[8], p[7], p[6], p[5], p[4], p[3], p[2], p[1], g[0]);
  wire c9_t9;
  and #(2) (c9_t9, p[8], p[7], p[6], p[5], p[4], p[3], p[2], p[1], p[0], cin);

  or #(2) (c[9], c9_t0, c9_t1, c9_t2, c9_t3, c9_t4, c9_t5, c9_t6, c9_t7, c9_t8, c9_t9);

  // c10 carry equation
  wire c10_t0;
  and #(2) (c10_t0, g[9]);
  wire c10_t1;
  and #(2) (c10_t1, p[9], g[8]);
  wire c10_t2;
  and #(2) (c10_t2, p[9], p[8], g[7]);
  wire c10_t3;
  and #(2) (c10_t3, p[9], p[8], p[7], g[6]);
  wire c10_t4;
  and #(2) (c10_t4, p[9], p[8], p[7], p[6], g[5]);
  wire c10_t5;
  and #(2) (c10_t5, p[9], p[8], p[7], p[6], p[5], g[4]);
  wire c10_t6;
  and #(2) (c10_t6, p[9], p[8], p[7], p[6], p[5], p[4], g[3]);
  wire c10_t7;
  and #(2) (c10_t7, p[9], p[8], p[7], p[6], p[5], p[4], p[3], g[2]);
  wire c10_t8;
  and #(2) (c10_t8, p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], g[1]);
  wire c10_t9;
  and #(2) (c10_t9, p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], p[1], g[0]);
  wire c10_t10;
  and #(2) (c10_t10, p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], p[1], p[0], cin);

  or #(2) (c[10], c10_t0, c10_t1, c10_t2, c10_t3, c10_t4, c10_t5, c10_t6, c10_t7, c10_t8, c10_t9, c10_t10);

  // c11 carry equation
  wire c11_t0;
  and #(2) (c11_t0, g[10]);
  wire c11_t1;
  and #(2) (c11_t1, p[10], g[9]);
  wire c11_t2;
  and #(2) (c11_t2, p[10], p[9], g[8]);
  wire c11_t3;
  and #(2) (c11_t3, p[10], p[9], p[8], g[7]);
  wire c11_t4;
  and #(2) (c11_t4, p[10], p[9], p[8], p[7], g[6]);
  wire c11_t5;
  and #(2) (c11_t5, p[10], p[9], p[8], p[7], p[6], g[5]);
  wire c11_t6;
  and #(2) (c11_t6, p[10], p[9], p[8], p[7], p[6], p[5], g[4]);
  wire c11_t7;
  and #(2) (c11_t7, p[10], p[9], p[8], p[7], p[6], p[5], p[4], g[3]);
  wire c11_t8;
  and #(2) (c11_t8, p[10], p[9], p[8], p[7], p[6], p[5], p[4], p[3], g[2]);
  wire c11_t9;
  and #(2) (c11_t9, p[10], p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], g[1]);
  wire c11_t10;
  and #(2) (c11_t10, p[10], p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], p[1], g[0]);
  wire c11_t11;
  and #(2) (c11_t11, p[10], p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], p[1], p[0], cin);

  or #(2) (c[11], c11_t0, c11_t1, c11_t2, c11_t3, c11_t4, c11_t5, c11_t6, c11_t7, c11_t8, c11_t9, c11_t10, c11_t11);

  // c12 carry equation
  wire c12_t0;
  and #(2) (c12_t0, g[11]);
  wire c12_t1;
  and #(2) (c12_t1, p[11], g[10]);
  wire c12_t2;
  and #(2) (c12_t2, p[11], p[10], g[9]);
  wire c12_t3;
  and #(2) (c12_t3, p[11], p[10], p[9], g[8]);
  wire c12_t4;
  and #(2) (c12_t4, p[11], p[10], p[9], p[8], g[7]);
  wire c12_t5;
  and #(2) (c12_t5, p[11], p[10], p[9], p[8], p[7], g[6]);
  wire c12_t6;
  and #(2) (c12_t6, p[11], p[10], p[9], p[8], p[7], p[6], g[5]);
  wire c12_t7;
  and #(2) (c12_t7, p[11], p[10], p[9], p[8], p[7], p[6], p[5], g[4]);
  wire c12_t8;
  and #(2) (c12_t8, p[11], p[10], p[9], p[8], p[7], p[6], p[5], p[4], g[3]);
  wire c12_t9;
  and #(2) (c12_t9, p[11], p[10], p[9], p[8], p[7], p[6], p[5], p[4], p[3], g[2]);
  wire c12_t10;
  and #(2) (c12_t10, p[11], p[10], p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], g[1]);
