  genvar j;
  generate
    for (j = 0; j < 64; j = j + 1) begin : gen_sum
      if (j == 0) begin
        xor #(2) (sum[j], p[j], cin);
      end
      else begin
        xor #(2) (sum[j], p[j], c[j]);
      end
    end
  endgenerate

endmodule
